from risk_learning import *
import html, importlib.util
s=importlib.util.spec_from_file_location('v31_report',V31/'src/report.py');shared=importlib.util.module_from_spec(s);s.loader.exec_module(shared)
LABELS={'baseline':'Existing neutral log-growth model','h21_original':'Original H21 challenger',
    'fixed_vol_scale':'Volatility scaling · existing model','retrained_vol_scale':'Volatility scaling · retrained',
    'fixed_sector_neutral':'Sector neutral · existing model','retrained_sector_neutral':'Sector neutral · retrained',
    'fixed_corr3_neutral':'Correlation-factor neutral · existing model','retrained_corr3_neutral':'Correlation-factor neutral · retrained'}
shared.LABELS.update(LABELS);table=shared.table;plt=shared.plt

def main():
    out=HERE/'reports';p=pd.read_csv(out/'performance.csv');q=read(out/'qa.json');status=read(out/'status.json');full=p.loc[p.period.eq('full')].set_index('arm');y22=p.loc[p.period.eq('stress_2022')].set_index('arm');secondary=p.loc[p.period.eq('secondary_2012_2023')].set_index('arm');window=p.loc[p.period.eq('drawdown_2021_2023')].set_index('arm')
    order=['h21_original','baseline',*ARMS];frame=full.reindex(order).reset_index();frame['return_2022']=frame.arm.map(y22.net_return);frame['cagr_2012']=frame.arm.map(secondary.cagr);frame['dd_2021_2023']=frame.arm.map(window.max_drawdown)
    returns=pd.read_csv(out/'daily_returns.csv.gz',index_col=0,parse_dates=True);growth=pd.read_csv(out/'paired_growth_full.csv');exposure=pd.read_csv(out/'actual_sector_exposure.csv');borrow=pd.read_csv(out/'borrow_sensitivity.csv');riskmap=pd.read_csv(out/'pre2022_sector_risk_map.csv');riskdate=read(out/'risk_map_audit.json')['date']
    assets=HERE/'assets';assets.mkdir(exist_ok=True);plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.18,'figure.facecolor':'white'})
    colors={'baseline':'#444b55','h21_original':'#868c94','fixed_vol_scale':'#ca8b24','retrained_vol_scale':'#ca8b24','fixed_sector_neutral':'#257d65','retrained_sector_neutral':'#257d65','fixed_corr3_neutral':'#596cb0','retrained_corr3_neutral':'#596cb0'}
    wealth=(1+returns).cumprod();draw=wealth/wealth.cummax().clip(lower=1)-1
    fig,axs=plt.subplots(3,1,figsize=(11,10),sharex=True)
    for ax,kind in zip(axs,KINDS):
        for a in ['baseline',f'fixed_{kind}',f'retrained_{kind}']:
            ax.plot(wealth[a],label=LABELS[a],color=colors[a],ls='--' if a.startswith('fixed') else '-',lw=1.6)
        ax.set_ylabel('Growth of $1');ax.legend(fontsize=8,loc='upper left');ax.set_title({'vol_scale':'Individual-stock volatility scaling','sector_neutral':'Sector net neutrality','corr3_neutral':'Top three residual-correlation factors neutral'}[kind])
    fig.suptitle('2007–2023: applying a risk control versus relearning under it',fontsize=14);fig.tight_layout();fig.savefig(assets/'full_wealth.png',dpi=170);plt.close(fig)
    fig,axs=plt.subplots(3,1,figsize=(11,10),sharex=True)
    for ax,kind in zip(axs,KINDS):
        for a in ['baseline',f'fixed_{kind}',f'retrained_{kind}']:
            ax.plot(draw.loc['2021':'2023',a]*100,label=LABELS[a],color=colors[a],ls='--' if a.startswith('fixed') else '-',lw=1.6)
        ax.set_ylabel('Drawdown (%)');ax.legend(fontsize=8,loc='lower left')
    fig.suptitle('2021–2023: drawdown from each strategy’s previous historical high',fontsize=14);fig.tight_layout();fig.savefig(assets/'drawdown_2022.png',dpi=170);plt.close(fig)
    cols=[('arm','Policy','text'),('cagr','2007–23 CAGR','pct'),('sharpe','Sharpe','num'),('volatility','Volatility','pct'),('max_drawdown','Max drawdown','pct'),('return_2022','2022 return','pct'),('cagr_2012','2012–23 CAGR','pct')]
    positive='; '.join(LABELS[a]+' versus '+LABELS[b] for a,b in status['positive_growth_holm_both_blocks']) or 'None';inf=growth.loc[growth.block_length.eq(60)];funding=borrow.loc[borrow.period.eq('full')].pivot(index='arm',columns='annual_borrow_bps',values='cagr').reindex(order).reset_index().rename(columns={0:'zero',100:'one',300:'three'})
    diag=exposure.loc[exposure.period.eq('stress_2022')];targetdiag=pd.DataFrame(q['target_checks']);best=full.loc[list(ARMS)].cagr.idxmax()
    body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>v34 · Stock volatility and correlated group exposure</title>
    <style>body{{margin:0;background:#f5f7fa;color:#19283b;font:16px/1.55 system-ui,sans-serif}}main{{max-width:1280px;margin:auto;padding:42px 26px}}h1{{font-size:34px;line-height:1.2}}h2{{margin-top:36px}}p{{max-width:1100px}}.scroll{{overflow-x:auto}}table{{width:100%;border-collapse:collapse;font-size:13px;background:white}}td,th{{padding:9px;border-bottom:1px solid #e2e7ed;white-space:nowrap;text-align:right}}td:first-child,th:first-child{{text-align:left}}thead{{background:#e9eff5}}.note{{padding:16px 20px;background:#fff3dd;border-left:4px solid #bc7b23}}img{{width:100%;height:auto;background:white}}a{{color:#245d9b}}code{{font-size:12px;overflow-wrap:anywhere}}</style><main>
    <h1>Stock volatility and correlated group exposure</h1><p>Six controlled comparisons isolate the effect of changing portfolio construction from retraining the nonlinear learner under that construction. The existing 21-session neutral log-growth model is the direct reference; the original H21 challenger is retained unchanged.</p>
    <p class="note">This is a targeted follow-up to an already observed 2022 failure. All rules were frozen before these new results, but the history is reused: 2022 is a retrospective diagnostic, not independent confirmation. Source valuation and universe qualifications remain. No candidate is automatically promoted.</p>
    <h2>Results across the full dataset</h2><p>The highest full-period CAGR among the six new arms is <strong>{html.escape(LABELS[best])}</strong>: {full.loc[best,'cagr']:.2%}, versus {full.loc['baseline','cagr']:.2%} for the existing neutral model. Positive annual-log-growth differences surviving the nine-comparison Holm family at both bootstrap block lengths: <strong>{html.escape(positive)}</strong>. Best observed performance is descriptive and is not a deployment decision.</p>
    {table(frame,cols)}<p>Returns include modeled trading costs of 2 bps per side. Borrow, financing and cash interest remain zero, as in the benchmark. Calendar-year 2022 figures use actual cumulative returns; the separate CAGR columns are annualized.</p>
    <img src="assets/full_wealth.png" alt="Full history performance separated by risk control">
    <h2>Why test this after 2022?</h2><p>An exact replay of the existing neutral model’s 2022 holdings found a −19.44% annual return: technology contributed −14.98 percentage points and energy −13.79 points, partly offset elsewhere. The average technology long exposure was about 51% of capital and energy short exposure about 36%. Individual stock limits did not control these aggregate bets. <a href="../v33_adaptive_beta/index.html">See the exact long/short and sector attribution.</a></p>
    <p>The risk map uses only the 63 sessions available at the {riskdate} decision. Volatility measures each stock’s movement size; correlation measures whether stocks move together. Their product determines covariance: covariance(i,j) = volatility(i) × volatility(j) × correlation(i,j). The original engine already estimated covariance for total risk sizing. These experiments additionally change which group risks the portfolio is allowed to carry.</p>
    <img src="assets/pre2022_risk_map.png" alt="Pre-2022 stock residual correlation map, original sector weights and individual stock volatilities">
    {table(riskmap,[('sector','Source sector','text'),('names','Names','num'),('net_forecast_weight','Original net target','pct'),('median_stock_volatility','Median stock volatility','pct'),('mean_within_sector_residual_correlation','Mean residual correlation','num')])}
    <h2>What changed in each test?</h2><ul><li><strong>Individual volatility:</strong> scale each raw score by median stock volatility divided by its own 63-session volatility, clipped to 0.5–2.0, before the existing dollar/beta projection and portfolio risk limits.</li><li><strong>Sector neutrality:</strong> jointly project scores to zero market beta and zero net allocation in every available source sector, treating Unknown separately. This tests within-sector stock selection.</li><li><strong>Correlation-factor neutrality:</strong> remove SPY from trailing stock returns, standardize residuals, extract the top three correlation components, and project to zero exposure to their raw-return loadings alongside dollar and market-beta neutrality.</li></ul>
    <p>Each control is applied first to the exact saved model coefficients, then used inside a fresh fit of the same nonlinear-feature learner. All six retain the same 58 inputs plus 32 nonlinear features, 21-session horizon and cadence, original efficacy gate, 12% forecast-volatility limit, cohort-adjusted gross cap of 3, 15% name cap, 20% trade buffer, next-close execution, data and daily account engine. No market-bias controller is added here. Risk controls determine sizing and allowable exposure; high volatility alone does not determine a short position.</p>
    <p>Sector and correlation-factor neutrality hold at scheduled desired targets. Existing daily beta/gross/eligibility guards remain; they do not enforce hard daily sector or principal-component limits. Price drift and execution can leave residual group exposure between decisions, measured below. The 63-session correlation estimate is noisy and the top three factors can omit relevant groups.</p>
    <p>The 12% forecast-volatility budget is a limit, not a promise of equal realized risk. After common exposures are removed, the unchanged gross or name cap can bind before that volatility limit. The following uses scheduled dates when the efficacy gate permits investment:</p>{table(targetdiag,[('arm','Policy','text'),('gate_on_forecast_vol','Mean forecast volatility','pct'),('gate_on_mean_gross','Mean gross / NAV','num'),('gate_on_gross_cap_binding','Gross cap binding','pct'),('gate_on_vol_limit_binding','Volatility limit binding','pct')])}
    <h2>The known 2022 stress window</h2><img src="assets/drawdown_2022.png" alt="2021 to 2023 historical drawdowns for fixed and retrained risk controls">
    {table(frame,[('arm','Policy','text'),('return_2022','2022 return','pct'),('dd_2021_2023','2021–23 max drawdown','pct')])}
    <p>Actual closing exposures in 2022, as fractions of account NAV:</p>{table(diag,[('arm','Policy','text'),('median_largest_sector_exposure','Median largest sector net','pct'),('p95_largest_sector_exposure','95th percentile largest sector net','pct'),('max_abs_sector_exposure','Largest observed sector net','pct'),('tech_mean_net','Average technology net','pct'),('energy_mean_net','Average energy net','pct')])}
    <h2>Inference and borrow sensitivity</h2><p>Primary endpoint: full-period annual log growth, with nine prespecified paired comparisons, 2,000-draw circular bootstraps and 20/60-session blocks. Holm correction is within this study and does not cover all earlier searches. The table shows the 60-session results; intervals are pointwise. Stress-window and drawdown changes are descriptive.</p>
    {table(inf,[('arm','Candidate','text'),('baseline','Reference','text'),('delta_annual_log_growth','Δ annual log growth','pct'),('ci_low','95% lower','pct'),('ci_high','95% upper','pct'),('p_holm','Holm p','num')])}
    <p>The following deducts illustrative borrow charges from prior-close short exposure while holding the trading path fixed. It does not model historical borrow availability or rerun the account with funding costs.</p>{table(funding,[('arm','Policy','text'),('zero','0 bp borrow CAGR','pct'),('one','100 bp CAGR','pct'),('three','300 bp CAGR','pct')])}
    <h2>Verification and research limits</h2><p>{q['models']} new annual models and {q['inner_validations']} inner daily-account validations pass strict label-end purges. Saved targets regenerate with maximum error {q['recomputed_target_max_error']:.2g}. All six account paths pass arithmetic and noncash-exposure checks. Scheduled target checks independently verify net/beta/group constraints, name/gross/risk limits and eligibility. Four focused tests cover sector projection, correlation projection, unchanged allocator identity and volatility-scaled log-growth gradients. Source and frozen implementation hashes are unchanged.</p>
    <p>Model coefficients are fitted only on mature labels and selected using prior daily-account log growth. The gradient objective still approximates the actual engine over 21 sessions. Source-sector history and conditional valuations are inherited; the additional group constraints do not fix those data limitations. The full available backtest ends in 2023 and supplies no fresh holdout for these targeted follow-ups.</p>
    <p><a href="protocol.json">Frozen protocol</a> · <a href="reports/qa.json">QA audit</a> · <a href="reports/performance.csv">Full and stress metrics</a> · <a href="reports/annual.csv">Annual returns</a> · <a href="reports/paired_growth_full.csv">Both-block growth inference</a> · <a href="reports/actual_sector_exposure.csv">Actual group exposure</a> · <a href="reports/pre2022_stock_risk_map.csv">Pre-2022 stock map data</a> · <a href="data/source_audit.csv">Risk input timestamp audit</a></p>
    <p>Related completed experiments: <a href="../v31_growth_long_bias/index.html">growth objectives and controlled long bias</a> · <a href="../v32_continuous_exposure/index.html">cash regime and model architecture</a> · <a href="../v33_adaptive_beta/index.html">adaptive beta and exact 2022 mechanics</a>.</p><p>Protocol SHA-256: <code>{status['protocol_sha256']}</code></p></main></html>'''
    (HERE/'index.html').write_text(body,encoding='utf-8');print(HERE/'index.html')
if __name__=='__main__':main()
